mapper.select:
/* User09Mapper.selectSelfJoinList */
WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
/* SELECT 컬럼 순서 = SelfJoinRowResult 생성자 인자 순서와 1:1 (record 위치 매핑). 휴대폰은 암호문 + LAST4 만 내보내고 마스킹은 서비스가 수행한다(평문 SQL 노출 금지). */ SELECT U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.SITE_CD AS siteCd , S.SITE_NM AS siteNm , U.NODE_CD AS nodeCd , N.NODE_NM AS nodeNm , U.MBL_NO_ENC AS mblNoEnc , U.MBL_NO_LAST4 AS mblNoLast4 , U.ACCOUNT_STATUS AS accountStatus , DATE_FORMAT(U.INSERT_DATE, '%Y-%m-%d %H:%i') AS applyDtime
FROM TB_USER U
LEFT JOIN TB_SITE S ON S.CMPNY_CD = U.CMPNY_CD AND S.SITE_CD = U.SITE_CD
/* 부서명은 사용자 본인 사업장 기준으로 조인한다(타 사업장 동일 코드 부서명 오표시 차단). */ LEFT JOIN TB_SITE_NODE N ON N.CMPNY_CD = U.CMPNY_CD AND N.SITE_CD = U.SITE_CD AND N.NODE_CD = U.NODE_CD
WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.ACCOUNT_STATUS = #{accountStatus}
AND EXISTS ( SELECT 1 FROM node_tree NT WHERE NT.CMPNY_CD = U.CMPNY_CD AND NT.SITE_CD = U.SITE_CD AND NT.NODE_CD = U.NODE_CD )
AND U.NODE_CD = #{nodeCd}
AND ( U.USER_ID LIKE CONCAT('%', #{userKeyword}, '%') OR U.USER_NM LIKE CONCAT('%', #{userKeyword}, '%') )
/* 최신 신청 우선. 동시각 tie-break 는 USER_CD. */ ORDER BY U.INSERT_DATE DESC, U.USER_CD DESC

mapper.sql:
WHERE A.CMPNY_CD      = #{gvCmpnyCd}
  AND A.RESOURCE_TYPE = 'SELF_JOIN_APPROVAL'
  AND A.DEL_YN        = 'N'
  AND U.SITE_CD       = #{siteCd}


  AND  IN ('APPROVE', 'REJECT')


  AND EXISTS (
      SELECT 1
      FROM node_tree NT
      WHERE NT.CMPNY_CD = U.CMPNY_CD
        AND NT.SITE_CD  = U.SITE_CD
        AND NT.NODE_CD  = U.NODE_CD
  )


  AND U.NODE_CD = #{nodeCd}



  AND ( U.USER_ID LIKE CONCAT('%', #{userKeyword}, '%')
     OR U.USER_NM LIKE CONCAT('%', #{userKeyword}, '%') )



  AND  = #{actionType}


/* 처리기간은 서비스 계층에서 datetime 문자열로 정규화해 넘어온다.
   DATE() 함수 술어를 쓰면 IX_AUDIT_LOG_RESOURCE 를 못 탄다. */

  AND A.INSERT_DATE >= #{startDtime}


  AND A.INSERT_DATE <= #{endDtime}

mapper.select:
/* User09Mapper.selectSelfJoinHistoryList */
WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
/* SELECT 컬럼 순서 = SelfJoinHistoryRowResult 생성자 인자 순서와 1:1 (record 위치 매핑). 휴대폰은 암호문 + LAST4 만 내보내고 마스킹은 서비스가 수행한다(평문 SQL 노출 금지). 입사일/직급은 감사 로그의 승인 당시 값 우선, 없으면(T1 배포 이전 적재분) 현재값 폴백. */ SELECT A.AUDIT_ID AS auditId , DATE_FORMAT(A.INSERT_DATE, '%Y-%m-%d %H:%i') AS processDtime , AS actionType , U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , S.SITE_NM AS siteNm , N.NODE_NM AS nodeNm , U.MBL_NO_ENC AS mblNoEnc , U.MBL_NO_LAST4 AS mblNoLast4 , DATE_FORMAT(U.INSERT_DATE, '%Y-%m-%d %H:%i') AS applyDtime , CASE WHEN = 'APPROVE' THEN COALESCE(JSON_UNQUOTE(JSON_EXTRACT(A.DETAIL, '$.hireDate')) COLLATE utf8mb4_unicode_ci , U.HIRE_DATE) END AS hireDate , R.BAIM_VAL_D_NM AS rankNm , COALESCE(P.USER_NM, A.USER_CD) AS processorNm , JSON_UNQUOTE(JSON_EXTRACT(A.DETAIL, '$.reason')) AS rejectReason
FROM TB_AUDIT_LOG A
/* 대상자(신청자). 스코프 판정의 유일한 근거이므로 INNER JOIN 이다(fail-closed). */ INNER JOIN TB_USER U ON U.CMPNY_CD = A.CMPNY_CD AND U.USER_CD = A.RESOURCE_KEY
/* 처리자 이름. 퇴사/삭제 등으로 없으면 서비스가 아니라 SQL 에서 USER_CD 로 폴백한다. */ LEFT JOIN TB_USER P ON P.CMPNY_CD = A.CMPNY_CD AND P.USER_CD = A.USER_CD
LEFT JOIN TB_SITE S ON S.CMPNY_CD = U.CMPNY_CD AND S.SITE_CD = U.SITE_CD
/* 부서명은 대상자 본인 사업장 기준으로 조인한다(타 사업장 동일 코드 부서명 오표시 차단). */ LEFT JOIN TB_SITE_NODE N ON N.CMPNY_CD = U.CMPNY_CD AND N.SITE_CD = U.SITE_CD AND N.NODE_CD = U.NODE_CD
/* 직급명[COM007]. 사용중지된 직급도 이름은 보여야 하므로 USE_YN 술어를 두지 않는다. ★승인 행에만 조인한다 — 입사일/직급은 "승인 시 지정한 값"이라 거부 행에는 존재하지 않는 개념이다. action 가드 없이 현재값 폴백을 걸면, 거부→재가입→승인 경로에서 거부 행에 나중 승인의 입사일·직급이 실려 "거부 시점에 없던 값"이 응답에 나간다(qa D1). 웹은 화면에서 막지만 응답 계약을 그대로 재사용하는 앱에서 그대로 노출된다. */ LEFT JOIN TB_BAIM_VAL_D R ON R.CMPNY_CD = A.CMPNY_CD AND R.BAIM_VAL_CD = 'COM007' AND = 'APPROVE' AND R.BAIM_VAL_D_CD = COALESCE(JSON_UNQUOTE(JSON_EXTRACT(A.DETAIL, '$.rankCd')) COLLATE utf8mb4_unicode_ci , U.RANK_CD)
/* 최신 처리 우선. 동시각 tie-break 는 AUDIT_ID (페이지 경계 중복/누락 방지). */ ORDER BY A.INSERT_DATE DESC, A.AUDIT_ID DESC LIMIT #{pageSize} OFFSET #{offset}

/* User09Mapper.selectSelfJoinHistoryCount */
WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
/* 사업장/부서/직급 조인은 건수에 영향이 없어 생략한다. 단 INNER JOIN TB_USER 와 historyWhere 는 목록과 반드시 동일해야 한다(불일치 = 페이저 붕괴). */ SELECT COUNT(1)
FROM TB_AUDIT_LOG A
INNER JOIN TB_USER U ON U.CMPNY_CD = A.CMPNY_CD AND U.USER_CD = A.RESOURCE_KEY

mapper.update:
/* User09Mapper.updateApproveSelfJoin */
UPDATE TB_USER
   SET HIRE_DATE        = #{hireDate}
     , EMPLOYMENT_TYPE  = #{employmentType}
     , RANK_CD          = #{rankCd}

     , AUTH_CD          = '99999'
     , USE_YN           = 'Y'
     , ACCOUNT_STATUS   = '01'
     , UPDATE_NO        = #{updateNo}
     , UPDATE_DATE      = NOW()
 WHERE CMPNY_CD       = #{cmpnyCd}
   AND USER_CD        = #{userCd}
   AND ACCOUNT_STATUS = '06'

/* User09Mapper.updateRejectSelfJoin */
UPDATE TB_USER
   SET ACCOUNT_STATUS   = '07'
     , USE_YN           = 'N'
     , UPDATE_NO        = #{updateNo}
     , UPDATE_DATE      = NOW()
 WHERE CMPNY_CD       = #{cmpnyCd}
   AND USER_CD        = #{userCd}
   AND ACCOUNT_STATUS = '06'

mapper.select:
/* User09Mapper.selectRankCdExists */
SELECT COUNT(1)
FROM TB_BAIM_VAL_D D
WHERE D.CMPNY_CD      = #{cmpnyCd}
  AND D.BAIM_VAL_CD   = 'COM007'
  AND D.BAIM_VAL_D_CD = #{rankCd}
  AND D.USE_YN        = 'Y'
